/**
 * SP2: the theme dimension in the resolver, and the pin that says today's
 * callers are untouched.
 *
 * The pin's fixture was generated from the resolver BEFORE this change
 * (`dev-scripts/generate-search-locations-fixture.ts`) and committed. It is
 * never regenerated by the code it holds still - a generator that runs in CI
 * turns a pin into a snapshot of whatever the code now does.
 */
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';

import { screenSearchLocations } from '../../src/screens/screen-resolution';
import { clearThemeRegistryCache, writeTheme } from '../../src/screens/theme-registry';
import expected from './fixtures/search-locations.json';

let root: string;

function board(): void {
  root = fs.mkdtempSync(path.join(os.tmpdir(), 'theme-locations-'));
  fs.writeFileSync(path.join(root, 'ConfConfig.info'), '');
  clearThemeRegistryCache();
}

/** A theme with the scope directories it is given, and no others. */
function theme(slug: string, scopes: string[]): void {
  writeTheme(root, {
    slug, title: slug, author: '', owner: '', dir: `Themes/${slug}`,
    widths: [80], doorTheme: '', status: 'live',
  });
  for (const scope of scopes) {
    fs.mkdirSync(path.join(root, 'Themes', slug, scope), { recursive: true });
  }
  clearThemeRegistryCache();
}

const dirs = (screen: string, opts: { nodeId: number; confId?: number; themeSlug?: string }) =>
  screenSearchLocations(root, screen, opts).map(l => l.dir.replace(root, '<root>'));

beforeEach(board);
afterEach(() => fs.rmSync(root, { recursive: true, force: true }));

/*
 * THE ORACLE MOVED ONCE, ON PURPOSE, 2026-09-16.
 *
 * Every NODE screen's list gained one entry at the END: `Screens/Node`, the
 * directory every node shares. The image COLLAPSES node screens into it and
 * gives each `Node<n>.info` a `SCREENS` tooltype pointing there; a board built
 * before that keeps icons with no tooltype, reads `Node<n>/`, and cannot see
 * anything the image now ships only in the shared directory - which is how 239
 * generated PETSCII screens sat on the live volume unreachable until 71 node
 * directories were mirrored by hand.
 *
 * It is LAST, so nothing is shadowed: a node with its own art keeps it. The
 * rest of this fixture is unchanged, and a node screen is still found in the
 * node's own directory first.
 */
describe('a board with no theme resolves exactly as it did before themes existed', () => {
  const cases = [
    { nodeId: 1, confId: 1 },
    { nodeId: 7, confId: 2 },
    { nodeId: 0, confId: undefined },
  ];

  for (const screen of ['LOGON', 'BULL', 'MENU', 'CONF_BULL', 'GOODBYE', 'NODE_BULL', 'AWAITSCREEN']) {
    for (const opts of cases) {
      const key = `${screen}|node=${opts.nodeId}|conf=${opts.confId ?? '-'}`;
      it(`${key} is byte-identical to the pre-theme resolver`, () => {
        const locations = screenSearchLocations(root, screen, opts).map(l => ({
          dir: l.dir.replace(root, '<root>'),
          desc: l.desc,
        }));
        expect(locations).toEqual((expected as Record<string, unknown>)[key]);
      });
    }
  }

  it('is identical for themeSlug "default" too - the default theme is not a directory', () => {
    theme('default', []);
    for (const screen of ['LOGON', 'MENU', 'BULL']) {
      expect(dirs(screen, { nodeId: 1, confId: 1, themeSlug: 'default' }))
        .toEqual(dirs(screen, { nodeId: 1, confId: 1 }));
    }
  });
});

describe('a theme shadows a scope without removing it', () => {
  it('puts its Node directory ahead of the node the caller is on', () => {
    theme('neon', ['Node']);
    expect(dirs('LOGON', { nodeId: 1, confId: 1, themeSlug: 'neon' }))
      .toEqual(['<root>/Themes/neon/Node', '<root>/Node1', '<root>/Screens/Node']);
  });

  it('puts its Conf/<n> ahead of BOTH conference locations, in number not directory name', () => {
    theme('neon', ['Conf/1']);
    // The conference-root-first order is what makes Conf1/MENU250.TXT the live
    // board's main menu; a theme has to come ahead of that, not just ahead of
    // Conf1/Screens.
    expect(dirs('MENU', { nodeId: 1, confId: 1, themeSlug: 'neon' }))
      .toEqual(['<root>/Themes/neon/Conf/1', '<root>/Conf1', '<root>/Conf1/Screens']);
  });

  it('puts its Board directory ahead of the board root and Screens/', () => {
    theme('neon', ['Board']);
    expect(dirs('BULL', { nodeId: 1, confId: 1, themeSlug: 'neon' }))
      .toEqual(['<root>/Themes/neon/Board', '<root>', '<root>/Screens']);
  });

  it('leaves a scope it has no directory for exactly as the board has it', () => {
    // A partial theme is usable from day one: the artist redraws the logon
    // screen and every other screen still resolves to the board's own.
    theme('neon', ['Node']);
    expect(dirs('BULL', { nodeId: 1, confId: 1, themeSlug: 'neon' }))
      .toEqual(['<root>', '<root>/Screens']);
    expect(dirs('MENU', { nodeId: 1, confId: 2, themeSlug: 'neon' }))
      .toEqual(['<root>/Conf2', '<root>/Conf2/Screens']);
  });

  it('serves every node from the one Node directory', () => {
    theme('neon', ['Node']);
    for (const nodeId of [0, 1, 7, 24]) {
      expect(dirs('LOGON', { nodeId, themeSlug: 'neon' })[0]).toBe('<root>/Themes/neon/Node');
    }
  });
});

describe('what the resolver refuses to treat as a theme', () => {
  it('a slug with no registry entry - a query parameter may not name a directory', () => {
    fs.mkdirSync(path.join(root, 'Themes', 'ghost', 'Board'), { recursive: true });
    expect(dirs('BULL', { nodeId: 1, confId: 1, themeSlug: 'ghost' }))
      .toEqual(['<root>', '<root>/Screens']);
  });

  it('a slug that is not a slug', () => {
    theme('neon', ['Board']);
    for (const bad of ['../escape', 'Neon', 'neon/../..', '']) {
      expect(dirs('BULL', { nodeId: 1, confId: 1, themeSlug: bad }))
        .toEqual(['<root>', '<root>/Screens']);
    }
  });

  it('a theme whose directory is not on the volume', () => {
    // Registered but never uploaded, or deleted underneath the registry.
    writeTheme(root, {
      slug: 'gone', title: 'Gone', author: '', owner: '', dir: 'Themes/gone',
      widths: [80], doorTheme: '', status: 'live',
    });
    clearThemeRegistryCache();
    expect(dirs('BULL', { nodeId: 1, confId: 1, themeSlug: 'gone' }))
      .toEqual(['<root>', '<root>/Screens']);
  });
});
